require "test_helper"
require "tempfile"

class ConnectedWorkflowTest < Minitest::Test
  def test_connected_catalog_upload_checkout_and_credential_isolation
    fixture = JSON.parse(File.read(File.expand_path("../connected-workflow.json", __dir__)))
    fixture["product"]["data"].merge!("id" => 120, "title" => "Design kit", "variants" => [])
    fixture["variant"]["data"].merge!("id" => 4321, "product_id" => 120)
    fixture["order"]["data"]["id"] = 9001
    fixture["upload"]["data"].merge!("id" => 55, "product_id" => 120, "variant_id" => 4321)
    calls = []
    stub_request(:any, %r{\Ahttp://127\.0\.0\.1:54321/}).to_return do |request|
      path = URI(request.uri).path
      calls << "#{request.method} #{path}"
      response = nil
      status = 200
      if path == "/oauth/token"
        refute request.headers.key?("Authorization")
        refute request.headers.key?("X-Store")
        response = {token_type: "Bearer", expires_in: 3600, access_token: "workflow-access", refresh_token: "workflow-refresh"}
      else
        assert_equal "Bearer workflow-key", request.headers["Authorization"]
        assert_equal "launch-lab", request.headers["X-Store"]
        case [request.method, path]
        when [:get, "/api/v2/products"]
          number = URI.decode_www_form(URI(request.uri).query || "").to_h.fetch("page", "1").to_i
          response = {data: number == 2 ? [] : [fixture["product"]["data"]], meta: {current_page: number, from: 1, last_page: 3, links: [], path: "http://127.0.0.1:54321/api/v2/products", per_page: 1, to: 1, total: 2}, links: {first: "?page=1", last: "?page=3", prev: number > 1 ? "?page=#{number - 1}" : nil, next: number < 3 ? "?page=#{number + 1}" : nil}}
        when [:post, "/api/v2/products"]
          refute JSON.parse(request.body).key?("section")
          status, response = 201, fixture["product"]
        when [:get, "/api/v2/products/120"]
          response = fixture["product"]
        when [:patch, "/api/v2/products/120"]
          body = JSON.parse(request.body)
          assert body.key?("section")
          assert_nil body["section"]
          fixture["product"]["data"]["title"] = body["title"]
          response = fixture["product"]
        when [:post, "/api/v2/products/120/variants"]
          assert_equal 1999, JSON.parse(request.body).dig("pricing", "price", "price")
          status, response = 201, fixture["variant"]
        when [:post, "/api/v2/products/120/variants/4321/deliverable/files"]
          assert_includes request.headers["Content-Type"], "multipart/form-data"
          assert_includes request.body, "design-file-bytes"
          status, response = 201, fixture["upload"]
        when [:post, "/api/v2/orders"]
          body = JSON.parse(request.body)
          assert_equal "maya@example.com", body["customer_email"]
          assert_equal({"4321" => {"quantity" => 1}}, body["product_variants"])
          status, response = 201, fixture["order"]
        when [:post, "/api/v2/orders/9001/checkout"]
          status, response = 201, fixture["order"].merge("message" => "Checkout created successfully.")
          response["data"]["payment"]["checkout_url"] = "https://checkout.example.test/session-9001"
        when [:get, "/api/v2/products/999"]
          status, response = 422, {type: "validation_error", code: "validation_failed", message: "Choose an existing product", param: "product", request_id: "req-workflow"}
        else
          flunk "Unexpected workflow request #{request.method} #{path}"
        end
      end
      {status: status, headers: {"Content-Type" => "application/json", "X-Request-ID" => "req-workflow"}, body: JSON.generate(response)}
    end
    client = SellApp::Client.new(api_key: "workflow-key", store: "launch-lab", base_url: "http://127.0.0.1:54321/api", max_retries: 0)
    assert_equal "Design kit", client.products.list(limit: 1).data.first.title
    created = client.products.create(title: "Design kit", description: "Templates for your next project.", visibility: "HIDDEN")
    retrieved = client.products.get(product: created.data.id)
    updated = client.products.update(product: retrieved.data.id, title: "Design kit revised", section: nil)
    assert_equal "Design kit revised", updated.data.title
    variant = client.product_variants.create(product: created.data.id, title: "Design kit", description: "Templates for your next project.", deliverable: {types: ["MANUAL"], data: {}}, pricing: {humble: false, price: {price: 1999, currency: "USD"}}, payment_methods: ["STRIPE"])
    upload = Tempfile.create(["design", ".txt"]) do |file|
      file.write("design-file-bytes"); file.flush
      client.variant_deliverable_files.upload(product: created.data.id.to_s, variant: variant.data.id, file: file.path)
    end
    assert_equal created.data.id, upload.data.product_id
    order = client.orders.create(customer_email: "maya@example.com", payment_method: "STRIPE", product_variants: {variant.data.id.to_s => {quantity: 1}})
    checkout = client.orders.create_checkout(order: order.data.id)
    assert_equal order.data.id, checkout.data.id
    assert_equal "https://checkout.example.test/session-9001", checkout.data.payment.checkout_url
    assert_equal "Checkout created successfully.", checkout.message
    pages = (1..3).map { |number| client.products.list(page: number, limit: 1).data.length }
    assert_equal [1, 0, 1], pages
    error = assert_raises(SellApp::ApiError) { client.products.get(product: 999) }
    assert_equal [422, "validation_failed", "product", "req-workflow"], [error.status, error.code, error.param, error.request_id]
    token = client.oauth.exchange_oauth_token(grant_type: "refresh_token", refresh_token: "workflow-refresh")
    assert_equal "workflow-access", token.access_token
    assert_equal 13, calls.length
  end
